import * as React from 'react';
import { Binding, DataContext, ModelObjectReference } from '@antimatterjs/react';

import { DefaultEffects, getTheme, Modal, MotionAnimations, Separator } from '@fluentui/react';

import { StackPanel } from './StackPanel';
import { TextBlock } from './TextBlock';
import { Control, IControlProps, IControlState } from './Control';
import { Style } from '../Style';
import { Grid } from './Grid';
import { ItemsControl } from './ItemsControl';
import { ButtonBase } from './Primitives/ButtonBase';

interface IDialogBoxCommon
{
    DialogTemplate?: (viewModel?: ModelObjectReference) => JSX.Element;
}
export interface IDialogBoxProps extends IControlProps, IDialogBoxCommon
{
    ViewModel?: ModelObjectReference | Binding   
}
export interface IDialogBoxState extends IControlState, IDialogBoxCommon
{
    ViewModel?: ModelObjectReference
}

export class DialogBox extends Control<IDialogBoxProps, IDialogBoxState>
{
    static DefaultStyle: Style<IDialogBoxProps> = new Style(
        {
            Template: (templatedParent: DialogBox) =>
            (
                <Modal styles={{
                    main: {
                        animation: `${MotionAnimations.slideDownIn.replace("100ms", "400ms")}, ${MotionAnimations.fadeIn.replace("100ms", "400ms")}`
                    }
                }}>
                    <DataContext Value={templatedParent.state.ViewModel}>
                        <Grid RowDefinitions={[
                            Grid.RowDefinition(),
                            Grid.RowDefinition(1, true),
                            Grid.RowDefinition(),
                            Grid.RowDefinition(),
                        ]}>

                            {/*Header*/}
                            <Grid ColumnDefinitions={[Grid.ColumnDefinition(), Grid.ColumnDefinition(1, true), Grid.ColumnDefinition()]}>
                                {/*Icon*/}
                                <div></div>

                                {/*Title Header*/}
                                <TextBlock Text={new Binding("Title")} />

                                {/*Close Butotn*/}
                                <ButtonBase Command={new Binding("CancelCommand") } />
                            </Grid>

                            {/*Body*/}
                            {
                                templatedParent.state.DialogTemplate?.call(templatedParent, templatedParent.state.ViewModel)
                            }

                            {/*Separator*/}
                            <Separator />

                            {/*Buttons*/}
                            <Grid ColumnDefinitions={[Grid.ColumnDefinition(1, true), Grid.ColumnDefinition(1, true)]}>
                                {/* Secondary Buttons */}
                                <ItemsControl ItemsSource={new Binding("SecondaryCommands")}
                                    ItemTemplate={(item) => (<div></div>)}>
                                </ItemsControl>

                                {/* Primary Buttons */}
                                <ItemsControl ItemsSource={new Binding("PrimaryCommands")}
                                    ItemTemplate={(item) => (<div></div>)}>
                                </ItemsControl>
                            </Grid>
                        
                        </Grid>
                    </DataContext>
                </Modal>
            )
        }
    );


}